                    qo.append(i)

        head = 0
        while head < len(qm):
            u = qm[head]
            head += 1
            du = d_m[u]
            for v in nbrs[u]:
                if owner_after[v] == 0 and d_m[v] > du + 1:
                    d_m[v] = du + 1
                    qm.append(v)
        head = 0
        while head < len(qo):
            u = qo[head]
            head += 1
            du = d_o[u]
            for v in nbrs[u]:
                if owner_after[v] == 0 and d_o[v] > du + 1:
                    d_o[v] = du + 1
                    qo.append(v)

        col0 = 0.0
        col1 = 0.0
        for v in range(N):
            if owner_after[v] != 0:
                continue
            dm = d_m[v]
            do = d_o[v]
            if dm < do and dm <= 2:
                col0 += pts[v] / (1.0 + dm)
            elif do < dm and do <= 2:
                col1 -= pts[v] / (1.0 + do)

        out[idx, 0] = col0 / total
        out[idx, 1] = col1 / total

    return out
